local function playIntroSound()
    pcall(function()
        local ids = {
            "rbxassetid://9125419430", -- cinematic whoosh-ish
            "rbxassetid://6026984224",
            "rbxassetid://5153734608",
        }
        for _, id in ipairs(ids) do
            local s = Instance.new("Sound")
            s.SoundId = id
            s.Volume = 0.7
            s.Parent = SoundService
            s:Play()
            task.delay(4, function() s:Destroy() end)
        end
    end)
end

local function showTrailer()
    local ok, err = pcall(function()
        local gui = Instance.new("ScreenGui")
        gui.Name = "ColdWTF_Trailer"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 99999
        gui.Parent = get_hui()

        local bg = Instance.new("Frame")
        bg.Size = UDim2.fromScale(1, 1)
        bg.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        bg.BackgroundTransparency = 1
        bg.BorderSizePixel = 0
        bg.Parent = gui

        local card = Instance.new("Frame")
        card.AnchorPoint = Vector2.new(0.5, 0.5)
        card.Position = UDim2.fromScale(0.5, 0.5)
        card.Size = UDim2.fromOffset(420, 280)
        card.BackgroundColor3 = Color3.fromRGB(12, 14, 18)
        card.BorderSizePixel = 0
        card.BackgroundTransparency = 1
        card.Parent = bg
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 12)

        local accent = Instance.new("Frame")
        accent.Size = UDim2.new(1, 0, 0, 3)
        accent.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        accent.BorderSizePixel = 0
        accent.Parent = card

        local title = Instance.new("TextLabel")
        title.BackgroundTransparency = 1
        title.Position = UDim2.fromOffset(24, 28)
        title.Size = UDim2.new(1, -48, 0, 36)
        title.Font = Enum.Font.GothamBlack
        title.TextSize = 28
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.fromRGB(240, 245, 255)
        title.Text = "cold.wtf"
        title.TextTransparency = 1
        title.Parent = card

        local sub = Instance.new("TextLabel")
        sub.BackgroundTransparency = 1
        sub.Position = UDim2.fromOffset(24, 68)
        sub.Size = UDim2.new(1, -48, 0, 22)
        sub.Font = Enum.Font.Gotham
        sub.TextSize = 14
        sub.TextXAlignment = Enum.TextXAlignment.Left
        sub.TextColor3 = Color3.fromRGB(255, 255, 255)
        sub.Text = "zeehood · silent · rage · visuals"
        sub.TextTransparency = 1
        sub.Parent = card

        local features = {
            "Universal aimbot + silent (safe Hit mode)",
            "Orbit nearest / target select + circle",
            "ESP · tracers · chams · FOV colors",
            "Da Hood: stomp · aura · skins · farm",
            "Keybinds unbound — bind what you need",
        }
        local lines = {}
        for i, text in ipairs(features) do
            local lab = Instance.new("TextLabel")
            lab.BackgroundTransparency = 1
            lab.Position = UDim2.fromOffset(24, 100 + (i - 1) * 22)
            lab.Size = UDim2.new(1, -48, 0, 20)
            lab.Font = Enum.Font.GothamMedium
            lab.TextSize = 13
            lab.TextXAlignment = Enum.TextXAlignment.Left
            lab.TextColor3 = Color3.fromRGB(180, 190, 210)
            lab.Text = "›  " .. text
            lab.TextTransparency = 1
            lab.Parent = card
            lines[i] = lab
        end

        local tip = Instance.new("TextLabel")
        tip.BackgroundTransparency = 1
        tip.Position = UDim2.fromOffset(24, 240)
        tip.Size = UDim2.new(1, -48, 0, 20)
        tip.Font = Enum.Font.Gotham
        tip.TextSize = 12
        tip.TextXAlignment = Enum.TextXAlignment.Left
        tip.TextColor3 = Color3.fromRGB(100, 110, 130)
        tip.Text = "RightShift opens menu after trailer"
        tip.TextTransparency = 1
        tip.Parent = card

        -- animate in
        TweenService:Create(bg, TweenInfo.new(0.45), { BackgroundTransparency = 0.35 }):Play()
        TweenService:Create(card, TweenInfo.new(0.5, Enum.EasingStyle.Quint), { BackgroundTransparency = 0 }):Play()
        task.wait(0.15)
        TweenService:Create(title, TweenInfo.new(0.35), { TextTransparency = 0 }):Play()
        TweenService:Create(sub, TweenInfo.new(0.35), { TextTransparency = 0 }):Play()
        for i, lab in ipairs(lines) do
            task.wait(0.08)
            TweenService:Create(lab, TweenInfo.new(0.25), { TextTransparency = 0 }):Play()
        end
        TweenService:Create(tip, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
        task.wait(3.2)
        -- animate out
        TweenService:Create(bg, TweenInfo.new(0.4), { BackgroundTransparency = 1 }):Play()
        TweenService:Create(card, TweenInfo.new(0.4), { BackgroundTransparency = 1 }):Play()
        for _, obj in ipairs({ title, sub, tip }) do
            TweenService:Create(obj, TweenInfo.new(0.3), { TextTransparency = 1 }):Play()
        end
        for _, lab in ipairs(lines) do
            TweenService:Create(lab, TweenInfo.new(0.3), { TextTransparency = 1 }):Play()
        end
        task.wait(0.45)
        gui:Destroy()
    end)
    if not ok then warn("[cold.wtf] trailer:", err) end
end

task.spawn(function()
    playIntroSound()
    showTrailer()
end)

