-- Life Sentence / hood anti-kick (poor connection)
pcall(function()
    local mt = getrawmetatable(game)
    local oldnc = mt.__namecall
    setreadonly(mt, false)
    mt.__namecall = newcclosure(function(self, ...)
        local method = getnamecallmethod()
        if C.AntiKick then
            if method == "Kick" or method == "kick" then
                return
            end
            local m = string.lower(tostring(method))
            if m:find("kick") then return end
        end
        return oldnc(self, ...)
    end)
    setreadonly(mt, true)
end)

pcall(function()
    if hookfunction and LP and LP.Kick then
        local oldKick
        oldKick = hookfunction(LP.Kick, newcclosure(function(self, ...)
            if C.AntiKick and self == LP then return end
            return oldKick(self, ...)
        end))
    end
end)

pcall(function()
    -- suppress common network kick remotes by name
    local function checkRemote(obj)
        if not obj then return end
        local n = string.lower(obj.Name)
        if n:find("kick") or n:find("anticheat") or n:find("ban") or n:find("poor") or n:find("connection") then
            if obj:IsA("RemoteEvent") and hookfunction then
                pcall(function()
                    hookfunction(obj.FireServer, newcclosure(function(...) end))
                end)
            end
        end
    end
    for _, d in ipairs(game:GetDescendants()) do
        if d:IsA("RemoteEvent") or d:IsA("RemoteFunction") then
            pcall(checkRemote, d)
        end
    end
end)

