local function alive(p)
    local c = p.Character
    if not c then return false end
    local h = c:FindFirstChildOfClass("Humanoid")
    return h and h.Health > 0
end

local function isKO(p)
    local c = p.Character
    if not c then return true end
    local h = c:FindFirstChildOfClass("Humanoid")
    if not h or h.Health <= 0 then return true end
    -- platform stand / ragdoll states
    local koState = false
    pcall(function()
        if h.PlatformStand then koState = true end
        local st = h:GetState()
        if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Dead then
            koState = true
        end
    end)
    if koState then return true end
    local be = c:FindFirstChild("BodyEffects") or c:FindFirstChild("Body Effects")
    if be then
        local names = {"K.O", "KO", "Knocked", "KnockedOut", "Dead", "Death", "SDeath", "Cuff", "Grabbed"}
        for _, n in ipairs(names) do
            local v = be:FindFirstChild(n)
            if v then
                if typeof(v) == "Instance" and v:IsA("BoolValue") and v.Value then return true end
                if typeof(v) == "boolean" and v then return true end
            end
        end
        -- any bool under BodyEffects named like ko
        for _, ch in ipairs(be:GetChildren()) do
            if ch:IsA("BoolValue") and ch.Value then
                local ln = string.lower(ch.Name)
                if ln:find("ko") or ln:find("knock") or ln:find("dead") or ln:find("death") or ln:find("ragdoll") then
                    return true
                end
            end
        end
    end
    if c:FindFirstChild("GRABBING_CONSTRAINT") then return true end
    if c:FindFirstChild("Knocked") then
        local k = c.Knocked
        if k:IsA("BoolValue") and k.Value then return true end
    end
    -- humanoid sit + no move often means knocked in some games
    if h.Sit and h.Health < h.MaxHealth * 0.15 then return true end
    return false
end

local function team(p)
    if not C.TeamCheck then return false end
    return LP.Team and p.Team and LP.Team == p.Team
end

local function partOf(p, prefer)
    local c = p.Character
    if not c then return nil end
    prefer = prefer or C.AimPart
    return c:FindFirstChild(prefer) or c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart")
end

local function w2s(v)
    local a, on = Cam:WorldToViewportPoint(v)
    return Vector2.new(a.X, a.Y), on and a.Z > 0
end

local function mpos() return UIS:GetMouseLocation() end


local function isWhitelisted(p)
    if not p then return false end
    if C.UseWhitelist == false then return false end
    -- shared table survives config reload
    local WL = rawget(getgenv(), "ColdWTF_WL")
    if type(WL) ~= "table" then
        WL = {}
        rawset(getgenv(), "ColdWTF_WL", WL)
    end
    C.Whitelist = WL
    local uid = tostring(p.UserId)
    if WL[uid] or WL[p.Name] or WL[p.DisplayName] then return true end
    local nl = string.lower(p.Name)
    local dl = string.lower(p.DisplayName or "")
    for key, on in pairs(WL) do
        if on then
            local k = string.lower(tostring(key))
            if k == nl or k == dl or k == uid then return true end
        end
    end
    return false
end

local function wlResolvePlayer(name)
    if not name or name == "" then return nil end
    if typeof(name) == "Instance" and name:IsA("Player") then return name end
    local s = tostring(name)
    local p = Players:FindFirstChild(s)
    if p and p:IsA("Player") then return p end
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr.Name == s or plr.DisplayName == s then return plr end
        if string.lower(plr.Name) == string.lower(s) then return plr end
        if string.lower(plr.DisplayName) == string.lower(s) then return plr end
    end
    return nil
end

local function wlAdd(name)
    local WL = rawget(getgenv(), "ColdWTF_WL")
    if type(WL) ~= "table" then WL = {} rawset(getgenv(), "ColdWTF_WL", WL) end
    C.Whitelist = WL
    local p = wlResolvePlayer(name)
    if p then
        WL[tostring(p.UserId)] = true
        WL[p.Name] = true
        WL[p.DisplayName] = true
        return p.Name
    end
    if name and tostring(name) ~= "" then
        WL[tostring(name)] = true
        return tostring(name)
    end
    return nil
end

local function wlRemove(name)
    local WL = rawget(getgenv(), "ColdWTF_WL")
    if type(WL) ~= "table" then return end
    local p = wlResolvePlayer(name)
    if p then
        WL[tostring(p.UserId)] = nil
        WL[p.Name] = nil
        WL[p.DisplayName] = nil
    end
    if name then WL[tostring(name)] = nil end
end

local function wlClear()
    local WL = rawget(getgenv(), "ColdWTF_WL")
    if type(WL) == "table" then table.clear(WL) end
    C.Whitelist = WL or {}
end

local function pass(p)
    if not p or p == LP then return false end
    if isWhitelisted(p) then return false end
    if not alive(p) or team(p) then return false end
    if C.KnockCheck and isKO(p) then return false end
    return true
end

local function playerFromPart(part)
    if not part then return nil end
    local model = part.Parent
    if not model then return nil end
    return Players:GetPlayerFromCharacter(model)
end

local function partOK(part)
    if not part or not part.Parent then return false end
    local plr = playerFromPart(part)
    if plr and isWhitelisted(plr) then return false end
    if plr and not pass(plr) then return false end
    return true
end

local function visible(part)
    if not C.WallCheck or not part then return true end
    local origin = Cam.CFrame.Position
    local target = part.Position
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local exclude = { LP.Character }
    if part.Parent then table.insert(exclude, part.Parent) end
    params.FilterDescendantsInstances = exclude
    params.IgnoreWater = true
    local result = workspace:Raycast(origin, target - origin, params)
    if not result then return true end
    return false
end

local function closestInFOV(radius, prefer)
    local mp, best, bd = mpos(), nil, radius or C.FOV
    for _, p in ipairs(Players:GetPlayers()) do
        if pass(p) then
            local part = partOf(p, prefer)
            if part and partOK(part) and visible(part) then
                if not (C.LimitDist and (part.Position - Cam.CFrame.Position).Magnitude > C.MaxDist) then
                    local sp, on = w2s(part.Position)
                    if on then
                        local d = (sp - mp).Magnitude
                        if d <= bd then bd = d best = part end
                    end
                end
            end
        end
    end
    return best
end

local function nearestPlayerPart()
    local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return closestInFOV(9999, "HumanoidRootPart") end
    local best, bd = nil, math.huge
    for _, p in ipairs(Players:GetPlayers()) do
        if pass(p) then
            local part = partOf(p, "HumanoidRootPart")
            if part and partOK(part) and visible(part) then
                local d = (part.Position - hrp.Position).Magnitude
                if d < bd then bd = d best = part end
            end
        end
    end
    return best
end

local function resolveAimTarget(prefer)
    prefer = prefer or C.AimPart
    if C.AimTargetMode == "Selected" and C.AimTarget and C.AimTarget ~= "" then
        local p = wlResolvePlayer(C.AimTarget)
        if p and pass(p) then
            local part = partOf(p, prefer)
            if part and partOK(part) and visible(part) then return part end
        end
        return nil
    end
    if C.AimTargetMode == "Nearest" then
        return nearestPlayerPart()
    end
    return closestInFOV(C.FOV, prefer)
end


local function getHoverPlayerPart()
    local mp = mpos()
    local unit = Cam:ViewportPointToRay(mp.X, mp.Y)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { LP.Character }
    params.IgnoreWater = true
    local result = workspace:Raycast(unit.Origin, unit.Direction * 800, params)
    if not result or not result.Instance then return nil end
    local inst = result.Instance
    local model = inst:FindFirstAncestorOfClass("Model")
    if not model then return nil end
    local plr = Players:GetPlayerFromCharacter(model)
    if not plr or not pass(plr) then return nil end
    return partOf(plr, "HumanoidRootPart")
end

local function orbitInRange(part)
    if not part then return false end
    if not C.OrbitAntiKick then return true end
    local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    local d = (part.Position - hrp.Position).Magnitude
    return d <= (C.OrbitMaxDist or 50)
end

local function resolveOrbitTarget()
    local function gate(part)
        if not part or not partOK(part) then return nil end
        local hrp = part.Parent and part.Parent:FindFirstChild("HumanoidRootPart") or part
        if not orbitInRange(hrp) then return nil end
        return hrp
    end
    -- LockOn: prefer aimbot lock, else FOV closest
    if C.OrbitMode == "LockOn" or C.OrbitLockOn then
        if locked and locked.Parent and partOK(locked) then
            local r = gate(locked)
            if r then return r end
        end
        local t = resolveAimTarget and resolveAimTarget(C.AimPart) or closestInFOV(C.FOV, C.AimPart)
        if t and partOK(t) then
            local r = gate(t)
            if r then locked = t return r end
        end
        if C.OrbitMode == "LockOn" then return nil end
    end
    if C.OrbitMode == "Selected" and C.OrbitTarget and C.OrbitTarget ~= "" then
        local p = wlResolvePlayer(C.OrbitTarget)
        if p and pass(p) then
            return gate(partOf(p, "HumanoidRootPart"))
        end
        return nil
    end
    return gate(nearestPlayerPart())
end


local _worldOrig = nil
local function captureWorld()
    if _worldOrig then return end
    pcall(function()
        _worldOrig = {
            Brightness = Lighting.Brightness,
            ClockTime = Lighting.ClockTime,
            FogStart = Lighting.FogStart,
            FogEnd = Lighting.FogEnd,
            FogColor = Lighting.FogColor,
            Ambient = Lighting.Ambient,
            OutdoorAmbient = Lighting.OutdoorAmbient,
        }
    end)
end

local function restoreWorld()
    if not _worldOrig then return end
    pcall(function()
        Lighting.Brightness = _worldOrig.Brightness
        Lighting.ClockTime = _worldOrig.ClockTime
        Lighting.FogStart = _worldOrig.FogStart
        Lighting.FogEnd = _worldOrig.FogEnd
        Lighting.FogColor = _worldOrig.FogColor
        Lighting.Ambient = _worldOrig.Ambient
        Lighting.OutdoorAmbient = _worldOrig.OutdoorAmbient
        local bloom = Lighting:FindFirstChild("ColdWTF_Bloom")
        if bloom then bloom.Enabled = false end
        local cc = Lighting:FindFirstChild("ColdWTF_CC")
        if cc then cc.Enabled = false end
    end)
end

local function applyWorld()
    captureWorld()
    if not C.WorldOn then
        restoreWorld()
        return
    end
    pcall(function()
        Lighting.Brightness = C.WorldBrightness
        if C.WorldClockOn then
            Lighting.ClockTime = C.WorldClock
        end
        Lighting.FogStart = C.WorldFogStart
        Lighting.FogEnd = C.WorldFogEnd
        Lighting.FogColor = C.WorldFogColor
        Lighting.Ambient = C.WorldAmbient
        Lighting.OutdoorAmbient = C.WorldOutdoor
        local bloom = Lighting:FindFirstChild("ColdWTF_Bloom")
        if not bloom then
            bloom = Instance.new("BloomEffect")
            bloom.Name = "ColdWTF_Bloom"
            bloom.Parent = Lighting
        end
        bloom.Enabled = C.WorldBloom
        bloom.Intensity = C.WorldBloomInt
        bloom.Size = 24
        bloom.Threshold = 0.8
        local cc = Lighting:FindFirstChild("ColdWTF_CC")
        if not cc then
            cc = Instance.new("ColorCorrectionEffect")
            cc.Name = "ColdWTF_CC"
            cc.Parent = Lighting
        end
        cc.Enabled = C.WorldCC
        cc.Saturation = C.WorldCCSat
        cc.Contrast = C.WorldCCContrast
    end)
end

local function playSfx(id)
    pcall(function()
        local s = Instance.new("Sound")
        s.SoundId = id s.Volume = 1 s.Parent = SoundService
        s:Play()
        task.delay(2, function() s:Destroy() end)
    end)
end

-- only play hit/kill when LOCAL player damages someone
local _dmgConnDone = {}
local function hookPlayerDamage(plr)
    if not plr or plr == LP or _dmgConnDone[plr] then return end
    _dmgConnDone[plr] = true
    local function attach(char)
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 3)
        if not hum then return end
        local last = hum.Health
        hum.HealthChanged:Connect(function(hp)
            local dropped = last - hp
            last = hp
            if dropped <= 0 or dropped > 250 then return end
            -- check if we recently shot / are aiming at them / in range with tool
            local myChar = LP.Character
            if not myChar then return end
            local tool = myChar:FindFirstChildOfClass("Tool")
            local myHrp = myChar:FindFirstChild("HumanoidRootPart")
            local theirHrp = char:FindFirstChild("HumanoidRootPart")
            if not myHrp or not theirHrp then return end
            local dist = (myHrp.Position - theirHrp.Position).Magnitude
            -- only count if we have a tool out OR very close (melee) and mouse recently down / silent active
            local attacking = tool ~= nil or dist < 12
            if not attacking then return end
            if dist > 400 then return end
            if C.HitSound then
                playSfx(HIT_SOUNDS[C.HitSoundName] or HIT_SOUNDS.Default)
            end
            if hp <= 0 and C.KillSound then
                playSfx(KILL_SOUNDS[C.KillSoundName] or KILL_SOUNDS.Default)
            end
        end)
    end
    if plr.Character then task.spawn(attach, plr.Character) end
    plr.CharacterAdded:Connect(function(c) task.spawn(attach, c) end)
end

for _, plr in ipairs(Players:GetPlayers()) do hookPlayerDamage(plr) end
Players.PlayerAdded:Connect(hookPlayerDamage)

local function predictedPos(part, amt)
    local pos = part.Position
    local hrp = part.Parent and part.Parent:FindFirstChild("HumanoidRootPart")
    if hrp then
        local vel = hrp.AssemblyLinearVelocity or hrp.Velocity or Vector3.zero
        if C.Resolver then vel = vel * Vector3.new(1, 0.15, 1) end
        pos = pos + vel * (amt or C.SilentPredAmt)
    end
    return pos
end

local function silentEnabled()
    if C.RageOn or rageActive then return true end
    if not C.SilentOn then return false end
    if C.SilentMode == "Always" then return true end
    return silentActive
end

local function updateSilent()
    if not silentEnabled() then silentPart = nil return end
    silentPart = closestInFOV(C.SilentFOV, C.SilentPart)
    if silentPart and not partOK(silentPart) then silentPart = nil end
end

----------------------------------------------------------------
-- SILENT AIM (anti-cheat safe)
-- No game __index hook — that triggers "IndexInstance" kicks.
-- Default: silent aim assist (mouse snap to target).
-- Optional Hit Hook is OFF by default (can kick on protected games).
----------------------------------------------------------------
local silentHooked = false
local function installHitHook()
    if silentHooked then return true end
    if not (hookmetamethod and newcclosure) then return false end
    local ok = pcall(function()
        local oldIndex
        oldIndex = hookmetamethod(game, "__index", newcclosure(function(self, key)
            if not C.SilentHitHook then
                return oldIndex(self, key)
            end
            if not C.SilentOn and not C.RageOn and not silentActive and not rageActive then
                return oldIndex(self, key)
            end
            if checkcaller and checkcaller() then
                return oldIndex(self, key)
            end
            if key ~= "Hit" and key ~= "hit" and key ~= "Target" and key ~= "target" then
                return oldIndex(self, key)
            end
            if not silentEnabled() then
                return oldIndex(self, key)
            end
            local part = silentPart
            if not part or not part.Parent then
                return oldIndex(self, key)
            end
            if typeof(self) ~= "Instance" or not self:IsA("Mouse") then
                return oldIndex(self, key)
            end
            if key == "Hit" or key == "hit" then
                local pos = C.SilentPred and predictedPos(part, C.SilentPredAmt) or part.Position
                return CFrame.new(pos)
            end
            if key == "Target" or key == "target" then
                return part
            end
            return oldIndex(self, key)
        end))
    end)
    silentHooked = ok
    return ok
end

-- safe silent: move mouse toward target (no metamethod) — works on all games
local function silentAssistSnap()
    if C.SilentHitHook then return end
    if not silentEnabled() then return end
    local part = silentPart
    if not part or not part.Parent then return end
    if not partOK(part) then return end
    local pos = C.SilentPred and predictedPos(part, C.SilentPredAmt) or part.Position
    local sp, on = w2s(pos)
    if not on then return end
    local mp = mpos()
    local dx, dy = sp.X - mp.X, sp.Y - mp.Y
    local dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1.5 then return end
    -- strong snap so shots land without Hit hook
    local str = math.clamp(dist * 0.85, 2, 120)
    dx, dy = dx / dist * str, dy / dist * str
    if mousemoverel then
        pcall(mousemoverel, dx, dy)
    end
end

local function hideOrbitCircle()
    for _, l in ipairs(orbitLines) do if l then pcall(function() l.Visible = false end) end end
end

local function drawOrbitCircle(center)
    if not C.OrbitCircle or not center or not HasDrawing then hideOrbitCircle() return end
    local n = C.OrbitCircleSegs
    while #orbitLines < n do
        local l = DNew("Line")
        if not l then break end
        l.Thickness = 1.5 l.Visible = false
        table.insert(orbitLines, l)
    end
    local r, y = C.OrbitRadius, center.Y
    local pts = {}
    for i = 0, n do
        local ang = (i / n) * math.pi * 2
        local world = Vector3.new(center.X + math.cos(ang) * r, y, center.Z + math.sin(ang) * r)
        local sp, on = w2s(world)
        pts[i] = { sp = sp, on = on }
    end
    for i = 1, math.min(n, #orbitLines) do
        local a, b, line = pts[i-1], pts[i], orbitLines[i]
        if line and a and b and a.on and b.on then
            line.From = a.sp line.To = b.sp line.Color = C.OrbitCircleColor line.Visible = true
        elseif line then line.Visible = false end
    end
end


local function doNoRecoil()
    if not C.NoRecoil then return end
    local char = LP.Character
    if not char then return end
    pcall(function()
        local be = char:FindFirstChild("BodyEffects")
        if be then
            for _, n in ipairs({"Recoil", "GunRecoil", "Reload", "Shake"}) do
                local v = be:FindFirstChild(n)
                if v and v:IsA("BoolValue") then v.Value = false end
                if v and v:IsA("NumberValue") then v.Value = 0 end
                if v and v:IsA("Vector3Value") then v.Value = Vector3.zero end
            end
        end
        -- camera shake reset
        if Cam then
            -- mild: keep camera type
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.CameraOffset = Vector3.zero
        end
        -- tool recoil attributes common in hood games
        local tool = char:FindFirstChildOfClass("Tool")
        if tool then
            for _, d in ipairs(tool:GetDescendants()) do
                if d:IsA("NumberValue") or d:IsA("IntValue") then
                    local ln = string.lower(d.Name)
                    if ln:find("recoil") or ln:find("shake") or ln:find("spread") then
                        d.Value = 0
                    end
                end
            end
        end
    end)
end


local _doorsRemoved = false
local function doRemoveDoors()
    if not C.RemoveDoors then return end
    pcall(function()
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("BasePart") then
                local n = string.lower(obj.Name)
                if n:find("door") or n:find("gate") or n:find("cell") then
                    obj.CanCollide = false
                    obj.Transparency = math.max(obj.Transparency, 0.5)
                end
            end
            if obj:IsA("Model") then
                local n = string.lower(obj.Name)
                if n:find("door") or n:find("gate") then
                    for _, p in ipairs(obj:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.CanCollide = false
                        end
                    end
                end
            end
            if obj:IsA("ProximityPrompt") and string.lower(obj.Name):find("door") then
                obj.Enabled = false
            end
        end
    end)
end


