local function tryStomp()
    if not C.AutoStomp then return end
    local ch = LP.Character
    if not ch then return end
    local hrp = ch:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and isKO(p) and p.Character then
            local thrp = p.Character:FindFirstChild("HumanoidRootPart")
            if thrp and (thrp.Position - hrp.Position).Magnitude < 8 then
                hrp.CFrame = CFrame.new(thrp.Position + Vector3.new(0, 2.5, 0))
            end
        end
    end
end

