local trailObj = nil
local function ensureTrail()
    local ch = LP.Character
    if not ch then return end
    local hrp = ch:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    if C.TrailOn then
        if not trailObj or not trailObj.Parent then
            local a0 = Instance.new("Attachment") a0.Name = "CWTrail0" a0.Parent = hrp
            local a1 = Instance.new("Attachment") a1.Name = "CWTrail1" a1.Position = Vector3.new(0,0,-1) a1.Parent = hrp
            local tr = Instance.new("Trail")
            tr.Name = "CWTrail" tr.Attachment0 = a0 tr.Attachment1 = a1
            tr.Lifetime = 0.4 tr.FaceCamera = true tr.Color = ColorSequence.new(C.TrailColor) tr.Parent = hrp
            trailObj = tr
        else
            trailObj.Color = ColorSequence.new(C.TrailColor) trailObj.Enabled = true
        end
    else
        for _, n in ipairs({"CWTrail","CWTrail0","CWTrail1"}) do
            local x = hrp:FindFirstChild(n)
            if x then x:Destroy() end
        end
        trailObj = nil
    end
end

local function applySkin(name)
    C.SkinName = name
    if name == "None" then return end
    local ch = LP.Character
    if not ch then return end
    local colors = {
        Gold = Color3.fromRGB(255,200,50), Neon = Color3.fromRGB(0,255,180),
        Galaxy = Color3.fromRGB(80,40,180), Inferno = Color3.fromRGB(255,60,20),
        Ice = Color3.fromRGB(140,220,255), Shadow = Color3.fromRGB(30,30,40),
        Ruby = Color3.fromRGB(200,20,60), Emerald = Color3.fromRGB(20,180,80),
        Diamond = Color3.fromRGB(200,230,255), Void = Color3.fromRGB(40,0,60),
        Matrix = Color3.fromRGB(0,255,70), Blood = Color3.fromRGB(140,0,20),
    }
    local col = colors[name] or Color3.new(1,1,1)
    for _, tool in ipairs(ch:GetChildren()) do
        if tool:IsA("Tool") then
            for _, d in ipairs(tool:GetDescendants()) do
                if d:IsA("BasePart") or d:IsA("MeshPart") then
                    pcall(function() d.Color = col d.Material = Enum.Material.Neon end)
                end
            end
        end
    end
end

