if fovF then fovF.Thickness = 1 fovF.NumSides = 64 fovF.Filled = true fovF.Transparency = 0.9 fovF.Visible = false end

local cross = {}
for i = 1, 4 do
    local l = DNew("Line")
    if l then l.Thickness = 1.5 l.Visible = false end
    cross[i] = l
end

local function mkEsp(p)
    if not HasDrawing or ESP[p] then return end
    local e = {
        box = DNew("Square"), fill = DNew("Square"), name = DNew("Text"), dist = DNew("Text"),
        hpBg = DNew("Square"), hpF = DNew("Square"), snap = DNew("Line"), tracer = DNew("Line"), c = {},
    }
    if e.box then e.box.Thickness = 1 e.box.Filled = false end
    if e.fill then e.fill.Filled = true e.fill.Transparency = 0.82 end
    if e.name then e.name.Center = true e.name.Outline = true e.name.Size = 14 end
    if e.dist then e.dist.Center = true e.dist.Outline = true e.dist.Size = 13 end
    if e.hpBg then e.hpBg.Filled = true e.hpBg.Color = Color3.new(0,0,0) e.hpBg.Transparency = 0.45 end
    if e.hpF then e.hpF.Filled = true end
    if e.snap then e.snap.Thickness = 1 end
    if e.tracer then e.tracer.Thickness = 1.2 end
    for i = 1, 8 do local l = DNew("Line") if l then l.Thickness = 1.6 end e.c[i] = l end
    ESP[p] = e
end

local function hide(e)
    if not e then return end
    for _, k in ipairs({"box","fill","name","dist","hpBg","hpF","snap","tracer"}) do
        if e[k] then e[k].Visible = false end
    end
    for i = 1, 8 do if e.c[i] then e.c[i].Visible = false end end
end

local function drop(p)
    local e = ESP[p]
    if not e then return end
    for _, o in pairs(e) do
        if type(o) == "table" then for _, x in pairs(o) do pcall(function() if x and x.Remove then x:Remove() end end) end
        else pcall(function() if o and o.Remove then o:Remove() end end) end
    end
    ESP[p] = nil lastHP[p] = nil
    if HL[p] then pcall(function() HL[p]:Destroy() end) HL[p] = nil end
end

pcall(function() Players.PlayerAdded:Connect(function(p) task.wait(0.2) mkEsp(p) end) end)
pcall(function() Players.PlayerRemoving:Connect(drop) end)
for _, p in ipairs(Players:GetPlayers()) do if p ~= LP then mkEsp(p) end end

local function corners(e, x, y, w, h, col)
    local L = math.clamp(math.min(w, h) * 0.28, 6, 18)
    local s = {
        {Vector2.new(x,y), Vector2.new(x+L,y)}, {Vector2.new(x,y), Vector2.new(x,y+L)},
        {Vector2.new(x+w,y), Vector2.new(x+w-L,y)}, {Vector2.new(x+w,y), Vector2.new(x+w,y+L)},
        {Vector2.new(x,y+h), Vector2.new(x+L,y+h)}, {Vector2.new(x,y+h), Vector2.new(x,y+h-L)},
        {Vector2.new(x+w,y+h), Vector2.new(x+w-L,y+h)}, {Vector2.new(x+w,y+h), Vector2.new(x+w,y+h-L)},
    }
    for i = 1, 8 do
        if e.c[i] then e.c[i].From = s[i][1] e.c[i].To = s[i][2] e.c[i].Color = col e.c[i].Visible = true end
    end
    if e.box then e.box.Visible = false end
end

