RunService.RenderStepped:Connect(function(dt)
    Cam = workspace.CurrentCamera or Cam
    local mp = mpos()

    pcall(function()
        if Options then
            if Options.AimKey and C.AimMode == "Hold" then aiming = Options.AimKey:GetState() end
            if Options.SilentKey and C.SilentMode == "Hold" then silentActive = Options.SilentKey:GetState() end
            if Options.RageKey and C.RageMode == "Hold" then rageActive = Options.RageKey:GetState() end
        end
    end)
    if C.AimMode == "Always" then aiming = C.AimOn end
    if C.SilentMode == "Always" then silentActive = C.SilentOn end
    if C.RageMode == "Always" then rageActive = C.RageOn end

    updateSilent()
    pcall(silentAssistSnap)

    -- silent auto shoot (visible target, no hover needed)
    if C.SilentAutoShoot and silentEnabled() and silentPart and partOK(silentPart) then
        if (tick() - lastFire) * 1000 >= C.SilentAutoInterval then
            lastFire = tick()
            if mouse1click then mouse1click()
            elseif mouse1press then mouse1press() task.wait() mouse1release() end
        end
    end

    if fovC then
        fovC.Position = mp fovC.Radius = C.FOV fovC.Color = C.FOVColor
        fovC.Visible = C.ShowFOV and (C.AimOn or C.SilentOn)
    end
    if fovF then
        fovF.Position = mp fovF.Radius = C.FOV fovF.Color = C.FOVColor
        fovF.Visible = C.ShowFOV and C.FOVFill and (C.AimOn or C.SilentOn)
    end

    -- crosshair
    local cx, cy = Cam.ViewportSize.X / 2, Cam.ViewportSize.Y / 2
    local gap, len = 4, 8
    if C.Crosshair and cross[1] then
        local col = C.CrosshairColor
        cross[1].From = Vector2.new(cx - gap - len, cy) cross[1].To = Vector2.new(cx - gap, cy) cross[1].Color = col cross[1].Visible = true
        cross[2].From = Vector2.new(cx + gap, cy) cross[2].To = Vector2.new(cx + gap + len, cy) cross[2].Color = col cross[2].Visible = true
        cross[3].From = Vector2.new(cx, cy - gap - len) cross[3].To = Vector2.new(cx, cy - gap) cross[3].Color = col cross[3].Visible = true
        cross[4].From = Vector2.new(cx, cy + gap) cross[4].To = Vector2.new(cx, cy + gap + len) cross[4].Color = col cross[4].Visible = true
    else
        for i = 1, 4 do if cross[i] then cross[i].Visible = false end end
    end

    if C.AAOn or C.Spinbot then
        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        if hrp and hum and hum.Health > 0 then
            local speed = C.Spinbot and C.SpinSpeed * 30 or C.AASpeed
            if C.AAYaw == "Spin" or C.Spinbot then aaYaw = (aaYaw + speed * dt) % 360
            elseif C.AAYaw == "Jitter" then aaYaw = (tick() % 0.2 < 0.1) and 60 or -60 end
            local vel = hrp.AssemblyLinearVelocity
            hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, math.rad(aaYaw), 0)
            hrp.AssemblyLinearVelocity = vel
        end
    end

    if C.VoidOn then
        voidT = voidT + dt
        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            if voidPhase == "out" and voidT >= C.VoidOut then
                voidPhase = "hide" voidT = 0
                hrp.CFrame = hrp.CFrame + Vector3.new(0, -250, 0)
            elseif voidPhase == "hide" and voidT >= C.VoidHide then
                voidPhase = "out" voidT = 0
                hrp.CFrame = hrp.CFrame + Vector3.new(0, 250, 0)
            end
        end
    end

    -- keep lock target fresh for orbit lock-on (even if aimbot not actively aiming)
    if locked and not partOK(locked) then locked = nil end
    if (C.OrbitOn and (C.OrbitMode == "LockOn" or C.OrbitLockOn)) or (C.AimOn and (aiming or C.AlwaysLock or C.AimMode == "Always")) then
        if not locked or not locked.Parent then
            local t = resolveAimTarget(C.AimPart)
            if t and partOK(t) then locked = t end
        end
    end

    if C.OrbitOn then
        local t = resolveOrbitTarget()
        if t and not partOK(t) then t = nil end
        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if t then
            drawOrbitCircle(t.Position)
            if hrp then
                local ang = tick() * C.OrbitSpeed
                local pos = t.Position + Vector3.new(math.cos(ang)*C.OrbitRadius, C.OrbitHeight, math.sin(ang)*C.OrbitRadius)
                hrp.CFrame = CFrame.new(pos, t.Position)
            end
        else hideOrbitCircle() end
    else hideOrbitCircle() end

    local aimLive = C.AimOn and (aiming or C.AlwaysLock or C.AimMode == "Always")
    if aimLive then
        local t = locked
        if (C.Sticky or C.AlwaysLock) and t and t.Parent and visible(t) then
            local sp, on = w2s(t.Position)
            if not C.AlwaysLock then
                if not on or (sp - mp).Magnitude > C.FOV * 1.4 then t = nil locked = nil end
            end
        else
            t = nil
            if not C.AlwaysLock then locked = nil end
        end
        if not t then
            t = resolveAimTarget(C.AimPart)
            locked = t
        end
        if t then
            local pred = t.Position
            if C.Predict and t.Parent then
                local r = t.Parent:FindFirstChild("HumanoidRootPart")
                if r then
                    local vel = r.AssemblyLinearVelocity or r.Velocity or Vector3.zero
                    pred = pred + vel * C.PredAmt
                end
            end
            if C.CameraLock then
                local sm = math.clamp(C.Smooth, 0.05, 1)
                Cam.CFrame = Cam.CFrame:Lerp(CFrame.lookAt(Cam.CFrame.Position, pred), sm)
            else
                local sp, on = w2s(pred)
                if on then
                    local sm = math.clamp(C.Smooth, 0.05, 1)
                    local dx, dy = (sp.X - mp.X) * sm, (sp.Y - mp.Y) * sm
                    if mousemoverel then mousemoverel(dx, dy)
                    else Cam.CFrame = Cam.CFrame:Lerp(CFrame.lookAt(Cam.CFrame.Position, pred), sm * 0.35) end
                end
            end
        end
    elseif not C.Sticky and not C.AlwaysLock then
        locked = nil
    end

    if C.TrigOn then
        local t = closestInFOV(20, C.AimPart)
        if t and partOK(t) then
            local plr = playerFromPart(t)
            local skip = false
            -- force knock check on trigger (ignore pass cache)
            if C.KnockCheck and plr and isKO(plr) then
                skip = true
            end
            if not skip and C.TrigHPCheck and plr then
                local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
                if not hum or hum.Health < C.TrigMinHP then skip = true end
            end
            if not skip then
                local sp, on = w2s(t.Position)
                if on and (sp - mp).Magnitude < 18 then
                    if (tick() - lastFire) * 1000 >= C.TrigInterval then
                        lastFire = tick()
                        if mouse1click then mouse1click()
                        elseif mouse1press then mouse1press() task.wait() mouse1release() end
                    end
                end
            end
        end
    end

    if C.RapidFire and UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
        if tick() - lastFire >= C.RapidDelay then lastFire = tick() tryRapid() end
    end

    pcall(tryStomp) pcall(antiStompTick) pcall(doKillAura) pcall(doAntiLock) pcall(doGodMode)
    pcall(doNoRecoil) pcall(doGunChams) pcall(doPlayerChams)
    if C.RemoveDoors and tick() % 2 < 0.05 then pcall(doRemoveDoors) end
    if tick() % 0.5 < dt then pcall(applyWorld) end
    pcall(ensureTrail) pcall(doAutoReload)
    if C.AutoFarm and tick() - lastFarm > 1.2 then lastFarm = tick() pcall(doAutoFarm) end
    if C.AutoBuy and tick() - lastBuy > 2 then lastBuy = tick() pcall(doAutoBuy) end

    for p, e in pairs(ESP) do
        if not p.Parent or not pass(p) then hide(e)
        else
            local ch = p.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if not hrp then hide(e)
            elseif C.LimitDist and (hrp.Position - Cam.CFrame.Position).Magnitude > C.MaxDist then hide(e)
            else
                local top = select(1, w2s((hrp.CFrame * CFrame.new(0, 3.1, 0)).Position))
                local bot = select(1, w2s((hrp.CFrame * CFrame.new(0, -3.1, 0)).Position))
                local mid, on = w2s(hrp.Position)
                if not on then hide(e)
                else
                    local h = math.max(math.abs(top.Y - bot.Y), 20)
                    local w = h * 0.72
                    local x, y = mid.X - w / 2, top.Y
                    local col = C.BoxColor
                    if C.Box then
                        if C.BoxStyle == "Corner" then corners(e, x, y, w, h, col)
                        else
                            for i = 1, 8 do if e.c[i] then e.c[i].Visible = false end end
                            if e.box then e.box.Position = Vector2.new(x,y) e.box.Size = Vector2.new(w,h) e.box.Color = col e.box.Visible = true end
                        end
                        if C.BoxFill and e.fill then e.fill.Position = Vector2.new(x,y) e.fill.Size = Vector2.new(w,h) e.fill.Color = col e.fill.Visible = true
                        elseif e.fill then e.fill.Visible = false end
                    else
                        if e.box then e.box.Visible = false end
                        if e.fill then e.fill.Visible = false end
                        for i = 1, 8 do if e.c[i] then e.c[i].Visible = false end end
                    end
                    if C.NameESP and e.name then
                        e.name.Visible = true e.name.Text = p.DisplayName or p.Name
                        e.name.Position = Vector2.new(mid.X, y - 18) e.name.Color = C.NameColor
                    elseif e.name then e.name.Visible = false end
                    if C.DistESP and e.dist then
                        e.dist.Visible = true
                        e.dist.Text = math.floor((hrp.Position - Cam.CFrame.Position).Magnitude) .. " m"
                        e.dist.Position = Vector2.new(mid.X, y + h + 5)
                        e.dist.Color = Color3.fromRGB(200,210,230)
                    elseif e.dist then e.dist.Visible = false end
                    if C.HPESP and hum and e.hpBg and e.hpF then
                        local pct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                        e.hpBg.Visible = true e.hpF.Visible = true
                        e.hpBg.Position = Vector2.new(x-6,y) e.hpBg.Size = Vector2.new(3,h)
                        e.hpF.Position = Vector2.new(x-6, y+h*(1-pct)) e.hpF.Size = Vector2.new(3, h*pct)
                        e.hpF.Color = Color3.fromRGB(255*(1-pct), 255*pct, 70)
                        local prev = lastHP[p]
                        if prev then
                            -- hitsound moved to local-damage tracker only
                            if prev > 0 and hum.Health <= 0 and C.KillSound then playSfx(KILL_SOUNDS[C.KillSoundName] or KILL_SOUNDS.Default) end
                        end
                        lastHP[p] = hum.Health
                    else
                        if e.hpBg then e.hpBg.Visible = false end
                        if e.hpF then e.hpF.Visible = false end
                    end
                    if e.snap then
                        e.snap.Visible = C.Snap
                        if C.Snap then
                            e.snap.From = Vector2.new(Cam.ViewportSize.X/2, Cam.ViewportSize.Y)
                            e.snap.To = Vector2.new(mid.X, y+h) e.snap.Color = C.SnapColor
                        end
                    end
                    if e.tracer then
                        e.tracer.Visible = C.TracerOn
                        if C.TracerOn then
                            e.tracer.From = Vector2.new(Cam.ViewportSize.X/2, Cam.ViewportSize.Y/2)
                            e.tracer.To = Vector2.new(mid.X, mid.Y) e.tracer.Color = C.TracerColor
                        end
                    end
                    if C.Chams then
                        local hl = HL[p]
                        if not hl then
                            hl = Instance.new("Highlight")
                            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                            hl.FillTransparency = 0.55 hl.Parent = get_hui()
                            HL[p] = hl
                        end
                        hl.Adornee = ch hl.FillColor = col hl.OutlineColor = Color3.new(1,1,1) hl.Enabled = true
                    elseif HL[p] then HL[p].Enabled = false end
                end
            end
        end
    end

    local ch = LP.Character
    if ch then
        local hum = ch:FindFirstChildOfClass("Humanoid")
        local hrp = ch:FindFirstChild("HumanoidRootPart")
        -- SAFE SPEED: never spam Humanoid.WalkSpeed (crashes many games)
        -- boost root velocity while moving instead
        if C.SpeedOn and hrp and hum then
            local ws = C.Speed
            if typeof(ws) == "number" and ws == ws and ws >= 8 and ws <= 50 then
                local move = hum.MoveDirection
                if move and move.Magnitude > 0.05 then
                    local flat = Vector3.new(move.X, 0, move.Z)
                    if flat.Magnitude > 0.01 then
                        local y = hrp.AssemblyLinearVelocity.Y
                        local boost = flat.Unit * ws
                        hrp.AssemblyLinearVelocity = Vector3.new(boost.X, y, boost.Z)
                    end
                end
            end
        end
        if hum and C.JumpPower then hum.JumpPower = C.JumpVal hum.UseJumpPower = true end
        if C.Noclip then
            for _, bp in ipairs(ch:GetDescendants()) do
                if bp:IsA("BasePart") then bp.CanCollide = false end
            end
        end
        if C.Flight and flightOn and hrp and hum then
            hum.PlatformStand = true
            local d = Vector3.zero
            if UIS:IsKeyDown(Enum.KeyCode.W) then d = d + Cam.CFrame.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.S) then d = d - Cam.CFrame.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.A) then d = d - Cam.CFrame.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.D) then d = d + Cam.CFrame.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then d = d + Vector3.yAxis end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then d = d - Vector3.yAxis end
            hrp.AssemblyLinearVelocity = d.Magnitude > 0 and d.Unit * C.FlightSpeed or Vector3.zero
        elseif hum and not (C.Flight and flightOn) then
            hum.PlatformStand = false
        end

        if C.ThirdPerson then
            pcall(function()
                LP.CameraMode = Enum.CameraMode.Classic
                local d = math.clamp(C.ThirdPersonDist, 4, 25)
                -- only zoom limits — do NOT write Cam.CFrame (flings camera)
                if LP.CameraMinZoomDistance ~= d then
                    LP.CameraMinZoomDistance = d
                end
                if LP.CameraMaxZoomDistance ~= d then
                    LP.CameraMaxZoomDistance = d
                end
            end)
        end

    end
end)

UIS.InputBegan:Connect(function(i, gp)
    if i.KeyCode == Enum.KeyCode.F7 then
        C.AimOn = false C.SilentOn = false C.RageOn = false C.TrigOn = false aiming = false
    end
end)

