    L:AddToggle("Snap", { Text = "Snap", Default = false, Callback = function(v) C.Snap = v end })
    L:AddLabel("Snap"):AddColorPicker("SnapColor", { Default = C.SnapColor, Title = "Snap", Callback = function(v) C.SnapColor = v end })
