do
    local W = Tabs.Visual:AddRightGroupbox("Whitelist")
    W:AddToggle("UseWhitelist", {
        Text = "Use Whitelist", Default = true,
        Callback = function(v) C.UseWhitelist = v end,
    })
    W:AddDropdown("WLPlayer", {
        SpecialType = "Player", Text = "Player",
        Callback = function(v) C._wlPick = v end,
    })
    W:AddButton({
        Text = "Add to Whitelist",
        Func = function()
            if C._wlPick and tostring(C._wlPick) ~= "" then
                local key = wlAdd(C._wlPick)
                if key then
                    local msg = key .. " whitelisted"
                    Library:Notify(msg, 3)
                    pcall(function()
                        StarterGui:SetCore("SendNotification", {
                            Title = "cold.wtf",
                            Text = msg,
                            Duration = 3,
                        })
                    end)
                else
                    Library:Notify("could not find player", 2)
                end
            else
                Library:Notify("pick a player first", 2)
            end
        end,
    })
    W:AddButton({
        Text = "Remove from Whitelist",
        Func = function()
            if C._wlPick then
                wlRemove(C._wlPick)
                Library:Notify("removed " .. tostring(C._wlPick), 2)
            end
        end,
    })
    W:AddButton({
        Text = "Clear Whitelist",
        Func = function()
            wlClear()
            Library:Notify("whitelist cleared", 2)
        end,
    })
    W:AddButton({
        Text = "Print Whitelist",
        Func = function()
            local list = {}
            for name in pairs(C.Whitelist) do table.insert(list, name) end
            Library:Notify(#list > 0 and table.concat(list, ", ") or "(empty)", 4)
            print("[cold.wtf] whitelist:", table.concat(list, ", "))
        end,
    })
end


