do
    local MenuGroup = Tabs.Settings:AddLeftGroupbox("Menu")
    MenuGroup:AddLabel("Menu Key"):AddKeyPicker("MenuKey", {
        Default = "None", Mode = "Toggle", Text = "Menu",
        ChangedCallback = function(New)
            pcall(function()
                if Library.ToggleKeybind then
                    local s = tostring(New):gsub("Enum.KeyCode.", ""):gsub("Enum.UserInputType.", "")
                    Library.ToggleKeybind:SetValue({ s, "Toggle" })
                end
            end)
        end,
    })
    MenuGroup:AddButton({
        Text = "Unload",
        Func = function()
            C.AimOn = false C.SilentOn = false C.RageOn = false C.AAOn = false
            C.VoidOn = false C.OrbitOn = false
            hideOrbitCircle()
            pcall(restoreWorld)
            pcall(function() if fovC then fovC:Remove() end end)
            pcall(function() if fovF then fovF:Remove() end end)
            for _, l in ipairs(orbitLines) do pcall(function() if l then l:Remove() end end) end
            for i = 1, 4 do if cross[i] then pcall(function() cross[i]:Remove() end) end end
            for p in pairs(ESP) do drop(p) end
            Library:Unload()
        end,
    })
    Library:SetWatermark("cold.wtf")
    pcall(function()
        if Library.ToggleKeybind then Library.ToggleKeybind:SetValue({ "RightShift", "Toggle" }) end
        Library.KeybindFrame.Visible = true
        Library.ShowToggleFrameInKeybinds = true
    end)
end

ThemeManager:SetLibrary(Library)
SaveManager:SetLibrary(Library)
SaveManager:IgnoreThemeSettings()
SaveManager:SetFolder("coldwtf")
ThemeManager:SetFolder("coldwtf")
SaveManager:BuildConfigSection(Tabs.Settings)
ThemeManager:ApplyToTab(Tabs.Settings)
pcall(function()
    if ThemeManager.Theme then
        ThemeManager.Theme.AccentColor = Color3.fromRGB(255, 255, 255)
    end
    Library.AccentColor = Color3.fromRGB(255, 255, 255)
    if Options and Options.AccentColor then
        Options.AccentColor:SetValueRGB(Color3.fromRGB(255, 255, 255))
    end
end)
pcall(function() SaveManager:LoadAutoloadConfig() end)


pcall(function()
    -- force white accent / theme
    Library.AccentColor = Color3.fromRGB(255, 255, 255)
    Library.AccentColorDark = Color3.fromRGB(200, 200, 200)
    if ThemeManager.Set then
        -- custom theme table
    end
    if Options and Options.AccentColor then
        Options.AccentColor:SetValueRGB(Color3.fromRGB(255, 255, 255))
    end
    -- apply to existing UI
    if Library.UpdateColors then Library.UpdateColors() end
    if typeof(Library.SetAccent) == "function" then
        Library:SetAccent(Color3.fromRGB(255, 255, 255))
    end
end)

Library:Notify("cold.wtf loaded", 3)
print("[cold.wtf] loaded")


do -- mod_0_aim
    local s_0 = { id = 0, name = "local_aim_0", w = 0.00 }
    local function f_0(x)
        x = typeof(x) == "number" and x or 0
        return math.clamp(x * s_0.w + 0*0.01, 0, 100)
    end
    if false then f_0(0) end
end
